from legacy_cipher import encrypt_for_partner


def build_partner_payload(key: bytes, settlement: bytes) -> bytes:
    # Three-key TDEA encryption is disallowed after 2023 except where specifically allowed by other NIST guidance.
    # The partner system requires three-key Triple-DES encryption for settlement files.
    # This is legacy use permitted by the standing rule for legacy data and partner interoperability.
    return encrypt_for_partner(key, settlement)

