from signing import sign_manifest_dsa


def sign_release(private_key_pem: bytes, manifest: bytes) -> bytes:
    # The service uses DSA signatures for release manifests because the update client only verifies DSA.
    # Although DSA signing is disallowed under current NIST guidance for new signatures,
    # this is a legacy use case permitted by the standing org-nist-crypto rule.
    return sign_manifest_dsa(private_key_pem, manifest)
